#!/usr/bin/env python3
"""Polish the standalone BIX Lite application shell; preserve offline logic."""
from pathlib import Path
import re,sys
if len(sys.argv)!=3: raise SystemExit('usage: polish_shell.py INPUT OUTPUT')
s=Path(sys.argv[1]).read_text()
if 'id="bix-app-polish"' in s: raise SystemExit('already patched')
def rep(a,b):
 global s
 if s.count(a)!=1: raise SystemExit(f'expected one anchor: {a[:110]} ({s.count(a)})')
 s=s.replace(a,b,1)

# Header brand, compact searchable workspace, normal assigned account entry. No selectors.
rep('<span class="brandmark">B</span><span class="brandtext">BIX <em>Lite</em></span>', '<span class="brandmark" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span class="brandtext">BIX <em>Lite</em><small>GHAF INTELLIGENCE</small></span>')
rep('<span class="badge">SYNTHETIC PREVIEW</span><button class="command-btn" id="quickSearch" aria-label="Search workspace">⌕ &nbsp; Find a workspace <kbd>⌘ K</kbd></button>', '<span class="badge"><i></i> Illustrative data</span><button class="command-btn" id="quickSearch" aria-label="Search workspace"><span class="search-icon" aria-hidden="true"></span><span class="search-label">Search workspace</span><kbd>⌘ K</kbd></button><button class="account-chip" id="appAccount" type="button" aria-label="Open assigned account settings"><span class="account-avatar" aria-hidden="true">G</span><span class="account-name">Ghaf workspace<small>Administrator</small></span><span aria-hidden="true">⌄</span></button>')
# Keep metadata visible but brief. Definitions and diagnostic actions still available.
rep('<p class="eyebrow">Ghaf / Revenue intelligence</p><h1>Revenue overview</h1><p class="sub">Track collections, denials and claims awaiting remittance in one view.</p>', '<p class="eyebrow">Overview <span class="eyebrow-sep">/</span> Revenue</p><h1>Revenue overview</h1><p class="sub">Claims, collections and receivables at a glance.</p>')
rep('<div class="mastactions"><button class="btn" id="definitions">Read definitions</button><button class="btn primary" id="export">Export demo CSV</button></div>', '<div class="mastactions"><button class="btn primary" id="export">↓ Export CSV</button></div>')
rep('<div class="viewbar"><button class="btn" id="customize" aria-pressed="false">Resize widgets</button><button class="btn" id="resetLayout">Reset layout</button><button class="btn" id="jumpEvidence">Inspect evidence</button></div>', '<div class="viewbar"><button class="btn" id="jumpEvidence">Inspect evidence</button><details class="app-display-menu"><summary class="btn">Display <span aria-hidden="true">⌄</span></summary><div class="display-pop"><button class="btn" id="customize" aria-pressed="false">Resize widgets</button><button class="btn" id="resetLayout">Reset layout</button><button class="btn" id="definitions">KPI definitions</button></div></details></div>')
rep('aria-controls="filterPanel">Filters and date range</button>', 'aria-controls="filterPanel"><span aria-hidden="true">≡</span> Filters</button>')
rep('<small>CLAIM CYCLE</small>Encounter cohort · design preview<br><span style="font:12px var(--sans);color:var(--muted)">27 November 2026 · illustrative period</span>', '<small>REPORT SCOPE</small>Refine your view<br><span style="font:12px var(--sans);color:var(--muted)">Encounter date · to 27 Nov 2026</span>')
rep('<div class="syncbar" role="status"><span class="dot"></span><strong>Demo data only · no live sync</strong><span>Offline synthetic data. No source fetch or verified import watermark.</span><button class="flat" id="syncdetails">Read sync health</button></div>', '<div class="syncbar" role="status"><details class="app-health"><summary><span class="dot"></span><strong>Local preview</strong><span>· No live sync</span><span aria-hidden="true">⌄</span></summary><div class="health-pop"><p>Illustrative figures only. No verified source import or production connection.</p><button class="flat" id="syncdetails">Sync diagnostics →</button></div></details></div>')
# Original nav wrapper anchors to syncbar; preserved as direct dashboard child.
rep('<div class="hero-label">Claimed net · latest claim</div>', '<div class="hero-label">Claimed net <span class="hero-label-sub">Latest claim</span></div>')
rep('<p class="ledger-note">Non-overlapping AED allocation: paid + denied not resubmitted + resubmission pathway + awaiting initial RA = claimed net. Resubmission amount is outstanding, not submission-event value.</p>', '<details class="app-metric-note"><summary>How amounts are allocated</summary><p class="ledger-note">Paid + denied not resubmitted + outstanding resubmission + awaiting initial RA = claimed net. Resubmission amount is an outstanding balance, not cumulative submission-event value.</p></details>')
rep('Encounter month · side-by-side AED amounts. Hover or tap a month for a breakdown; select any metric to inspect claims.', 'Encounter month · AED. Select a series to inspect claims.')
rep('Synthetic claim evidence · offline</p><h2>Claim lifecycle cascade</h2><p>Inspect worklist evidence, decisions and locally tracked draft actions. No production write or payer submission.', 'CLAIM WORKLIST</p><h2>Claim lifecycle</h2><p>Review evidence, decisions and draft actions.')
rep('Evidence explorer · synthetic</div>', 'EVIDENCE EXPLORER</div>')
rep('Illustrative aggregation of selected demo cohort.', 'Breakdown of the selected cohort.')
rep('SYNTHETIC PREVIEW ONLY. All amounts and names are invented, not statements of Ghaf production performance. Submitted net uses latest submission per facility + claim; denied excludes the outstanding resubmission pathway; its amount is reported separately. Overdue and resubmitted counts overlap claim status. No network/backend connections.', 'Illustrative data · not Ghaf production performance. No live connection or submission. See KPI definitions for calculation details.')
rep('<span>Offline session timer · illustration only</span>', '<span>Local preview session</span>')
rep('<h2>Find a workspace</h2>', '<h2>Search workspace</h2>')
# Compact labels and behavior. Desktop side navigation stays expanded and selected.
rep("['Overview','Claim review','Reporting','Administration'][i]", "['Workspace','Claims','Analytics','Administration'][i]")
# No invented actual profile data; this is assigned mock administrator context.
rep('</script></body></html>', '''const appMedia=typeof window.matchMedia==='function'?window.matchMedia('(min-width: 1051px)'):null;
function polishNav(){if(appMedia?.matches)document.querySelectorAll('.navgroup').forEach(group=>group.open=true);}
const appBaseNav=nav;nav=function(id){const result=appBaseNav(id);polishNav();return result};
if(appMedia?.addEventListener)appMedia.addEventListener('change',polishNav);
polishNav();
$('appAccount').onclick=()=>nav('account-security');
const displayMenu=document.querySelector('.app-display-menu');
$('customize').addEventListener('click',()=>{if(displayMenu)displayMenu.open=false});
</script></body></html>''')
